"""Orbit Wars — Entity Transformer Agent (auto-exported, do not edit)"""

import base64
import io
import math

import numpy as np
import torch
import torch.nn as nn
import torch.nn.functional as F

from kaggle_environments.envs.orbit_wars.orbit_wars import CENTER, ROTATION_RADIUS_LIMIT

# --- Hyperparameters (inlined from ModelConfig) ---
NUM_ANGLE_BINS = 72
NUM_SHIP_BINS = 16
ANGLE_BIN_WIDTH = 2 * math.pi / NUM_ANGLE_BINS
BOARD_SIZE = 100.0
SUN_RADIUS = 10.0
CENTER_XY = 50.0
MAX_SPEED = 6.0
MAX_OWNED = 10
_ENTITY_DIM = 96
_NUM_HEADS = 4
_NUM_LAYERS = 3
_MLP_EXP = 3
_PLANET_DIM = 18
_FLEET_DIM = 9
_GLOBAL_DIM = 10
_MAX_PLANETS = 48
_MAX_FLEETS = 128
_FIRE_THRESHOLD = 0.5


# --- Embedded parameters (base64-encoded torch state_dict) ---
_PARAMS_B64 = """"""


# --- Model architecture (mirrors model.py) ---

class _Block(nn.Module):
    def __init__(self, dim, heads, mlp_exp, dropout=0.0):
        super().__init__()
        self.attn = nn.MultiheadAttention(dim, heads, dropout=dropout, batch_first=True)
        self.ln1 = nn.LayerNorm(dim)
        self.ln2 = nn.LayerNorm(dim)
        self.mlp = nn.Sequential(
            nn.Linear(dim, dim * mlp_exp), nn.GELU(), nn.Dropout(dropout),
            nn.Linear(dim * mlp_exp, dim), nn.Dropout(dropout),
        )

    def forward(self, x, mask=None):
        a, _ = self.attn(x, x, x, key_padding_mask=mask)
        x = self.ln1(x + a)
        return self.ln2(x + self.mlp(x))


class _Model(nn.Module):
    def __init__(self):
        super().__init__()
        D = _ENTITY_DIM
        self.planet_proj = nn.Linear(_PLANET_DIM, D)
        self.fleet_proj = nn.Linear(_FLEET_DIM, D)
        self.global_proj = nn.Linear(_GLOBAL_DIM, D)
        self.mode_proj = nn.Linear(_GLOBAL_DIM, D)
        self.blocks = nn.ModuleList([_Block(D, _NUM_HEADS, _MLP_EXP) for _ in range(_NUM_LAYERS)])
        self.fire_head = nn.Linear(D, 1)
        self.angle_head = nn.Linear(D, NUM_ANGLE_BINS)
        self.ship_head = nn.Linear(D, NUM_SHIP_BINS)
        self.value_fc1 = nn.Linear(D, D)
        self.value_fc2 = nn.Linear(D, D // 2)
        self.value_out = nn.Linear(D // 2, 1)

    def forward(self, pf, ff, gf, pm, fm, fire_mask=None, angle_mask=None,
                slot_valid=None, owned_indices=None):
        B, D = pf.shape[0], _ENTITY_DIM
        planet_emb = self.planet_proj(pf)
        fleet_emb = self.fleet_proj(ff)
        global_emb = self.global_proj(gf) + self.mode_proj(gf)
        entities = torch.cat([global_emb.unsqueeze(1), planet_emb, fleet_emb], dim=1)

        N = entities.shape[1]
        attn_mask = torch.ones(B, N, dtype=torch.bool)
        attn_mask[:, 0] = False
        attn_mask[:, 1:1+pf.shape[1]] = ~pm
        attn_mask[:, 1+pf.shape[1]:] = ~fm

        x = entities
        for block in self.blocks:
            x = block(x, mask=attn_mask)

        if owned_indices is None:
            owned_indices = torch.zeros(B, MAX_OWNED, dtype=torch.long)
        fi = (owned_indices + 1).clamp(0, x.shape[1] - 1)
        bi = torch.arange(B).unsqueeze(1).expand(-1, MAX_OWNED)
        oe = x[bi, fi]

        fl = self.fire_head(oe).squeeze(-1)
        al = self.angle_head(oe)
        sl = self.ship_head(oe)

        if fire_mask is not None:
            fl = fl.masked_fill(~fire_mask, -100.0)
        if angle_mask is not None:
            al = al.masked_fill(~angle_mask, -100.0)
        if slot_valid is not None:
            fl = fl.masked_fill(~slot_valid, -100.0)
            al = al.masked_fill(~slot_valid.unsqueeze(-1), -100.0)
            sl = sl.masked_fill(~slot_valid.unsqueeze(-1), -100.0)

        vf = (~attn_mask).float()
        pooled = (x * vf.unsqueeze(-1)).sum(1) / vf.sum(1, keepdim=True).clamp(min=1)
        v = self.value_out(F.gelu(self.value_fc2(F.gelu(self.value_fc1(pooled))))).squeeze(-1)
        return dict(fire_logits=fl, angle_logits=al, ship_logits=sl, value=v)


# --- Lazy model loader ---
_model_cache = [None]

def _get_model():
    if _model_cache[0] is not None:
        return _model_cache[0]
    m = _Model()
    buf = io.BytesIO(base64.b64decode(_PARAMS_B64))
    try:
        sd = torch.load(buf, map_location="cpu", weights_only=True)
    except Exception:
        sd = torch.load(buf, map_location="cpu", weights_only=False)
    m.load_state_dict(sd)
    m.eval()
    _model_cache[0] = m
    return m


# --- Feature extraction (inlined from features.py) ---
















BOARD_SIZE = 100.0
SUN_RADIUS = 10.0
MAX_SPEED = 6.0


def fleet_speed(ships):
    ships = max(1, int(ships))
    scale = (math.log(ships) / math.log(1000.0)) ** 1.5
    return 1.0 + (MAX_SPEED - 1.0) * min(scale, 1.0)


def extract_features(obs, player, num_players=2, max_planets=48, max_fleets=128):
    """Extract entity features from observation dict.

    Returns dict of torch tensors (no batch dim).
    """
    planets = obs["planets"]
    fleets = obs["fleets"]
    step = obs.get("step", 0)
    angular_velocity = obs.get("angular_velocity", 0.0)
    initial_planets = obs.get("initial_planets", planets)
    comet_planet_ids = set(obs.get("comet_planet_ids", []))

    n_planets = len(planets)
    n_fleets = min(len(fleets), max_fleets)

    # --- Planet features (18) ---
    planet_feats = np.zeros((max_planets, 18), dtype=np.float32)
    planet_mask = np.zeros(max_planets, dtype=np.bool_)
    owned_indices_count = 0
    owned_indices = np.zeros(10, dtype=np.int64)  # max 10 owned planets
    owned_count = 0

    # Pre-compute initial planet lookup for orbit prediction
    init_by_id = {}
    for p in initial_planets:
        init_by_id[int(p[0])] = p

    # Pre-compute fleet pressure arrays
    fleet_x = np.array([f[2] for f in fleets[:n_fleets]], dtype=np.float32) if n_fleets > 0 else np.array([], dtype=np.float32)
    fleet_y = np.array([f[3] for f in fleets[:n_fleets]], dtype=np.float32)
    fleet_cos = np.array([math.cos(f[4]) for f in fleets[:n_fleets]], dtype=np.float32)
    fleet_sin = np.array([math.sin(f[4]) for f in fleets[:n_fleets]], dtype=np.float32)
    fleet_owner = np.array([f[1] for f in fleets[:n_fleets]], dtype=np.int32)
    fleet_ships_arr = np.array([f[6] for f in fleets[:n_fleets]], dtype=np.float32)

    for i, p in enumerate(planets[:max_planets]):
        planet_mask[i] = True
        pid, owner, x, y, radius, ships, production = p[0], p[1], p[2], p[3], p[4], p[5], p[6]

        dist_to_sun = math.hypot(x - CENTER, y - CENTER)
        is_orbiting = (dist_to_sun + radius) < ROTATION_RADIUS_LIMIT
        is_comet = int(pid) in comet_planet_ids
        is_home = (owner == player) and (ships <= 10 + production * 5) and (ships >= 10 - production)

        # Orbit prediction: position 5 turns ahead
        init_p = init_by_id.get(int(pid), p)
        rx = init_p[2] - CENTER
        ry = init_p[3] - CENTER
        init_angle = math.atan2(ry, rx)
        orbital_r = math.hypot(rx, ry)
        future_angle = init_angle + angular_velocity * (step + 5)
        pred_x = CENTER + orbital_r * math.cos(future_angle) if is_orbiting else x
        pred_y = CENTER + orbital_r * math.sin(future_angle) if is_orbiting else y

        # Incoming fleet pressure
        friendly_pressure = 0.0
        enemy_pressure = 0.0
        if n_fleets > 0:
            vx = x - fleet_x
            vy = y - fleet_y
            along = vx * fleet_cos + vy * fleet_sin
            perp = np.abs(vx * fleet_sin - vy * fleet_cos)
            incoming = (along > 0) & (perp < radius + 1.5)
            friendly_pressure = float(np.sum(fleet_ships_arr[incoming & (fleet_owner == player)]))
            enemy_pressure = float(np.sum(fleet_ships_arr[incoming & (fleet_owner != player) & (fleet_owner >= 0)]))

        # Capture cost
        if owner == -1:
            capture_cost = ships + 1
        elif owner != player:
            capture_cost = ships + production * 3 + 1
        else:
            capture_cost = 0.0

        # Distance to nearest owned planet
        min_owned_dist = 100.0
        for j, q in enumerate(planets[:max_planets]):
            if q[1] == player:
                d = math.hypot(x - q[2], y - q[3])
                min_owned_dist = min(min_owned_dist, d)
        if not any(q[1] == player for q in planets[:max_planets]):
            min_owned_dist = 0.0

        # Owner encoding: player=1, neutral=0, enemy=-1
        owner_emb = 1.0 if owner == player else (-1.0 if owner >= 0 else 0.0)

        planet_feats[i] = [
            (x - CENTER) / CENTER,       # 0: normalized x
            (y - CENTER) / CENTER,       # 1: normalized y
            owner_emb,                    # 2: owner encoding
            radius / 2.0,                 # 3: normalized radius
            math.log1p(ships) / 8.0,      # 4: log-normalized ships
            production / 5.0,             # 5: normalized production
            float(is_orbiting),           # 6: is_orbiting
            float(is_comet),              # 7: is_comet
            dist_to_sun / CENTER,         # 8: normalized dist to sun
            orbital_r / CENTER,           # 9: normalized orbital radius
            (pred_x - CENTER) / CENTER,   # 10: predicted x
            (pred_y - CENTER) / CENTER,   # 11: predicted y
            friendly_pressure / 100.0,    # 12: incoming friendly pressure
            enemy_pressure / 100.0,       # 13: incoming enemy pressure
            math.log1p(capture_cost) / 8.0,  # 14: capture cost
            min_owned_dist / BOARD_SIZE,  # 15: dist to nearest owned
            float(is_home),               # 16: is_home
            1.0,                          # 17: active mask
        ]

        # Track owned planets
        if owner == player and owned_count < 10:
            owned_indices[owned_count] = i
            owned_count += 1

    # --- Fleet features (9) ---
    fleet_feats = np.zeros((max_fleets, 9), dtype=np.float32)
    fleet_mask_arr = np.zeros(max_fleets, dtype=np.bool_)

    for i, f in enumerate(fleets[:max_fleets]):
        fleet_mask_arr[i] = True
        fid, owner, x, y, angle, from_pid, ships = f[0], f[1], f[2], f[3], f[4], f[5], f[6]
        speed = fleet_speed(ships)
        dist_sun = math.hypot(x - CENTER, y - CENTER)
        owner_emb = 1.0 if owner == player else (-1.0 if owner >= 0 else -0.5)

        fleet_feats[i] = [
            (x - CENTER) / CENTER,   # 0: normalized x
            (y - CENTER) / CENTER,  # 1: normalized y
            owner_emb,               # 2: owner encoding
            math.cos(angle),         # 3: angle cos
            math.sin(angle),         # 4: angle sin
            math.log1p(ships) / 8.0, # 5: log ships
            speed / MAX_SPEED,       # 6: normalized speed
            dist_sun / CENTER,       # 7: dist to sun
            1.0,                     # 8: active mask
        ]

    # --- Global features (10) ---
    total_owned_ships = sum(p[5] for p in planets if p[1] == player)
    total_owned_production = sum(p[6] for p in planets if p[1] == player)
    num_owned = sum(1 for p in planets if p[1] == player)
    total_enemy_ships = sum(p[5] for p in planets if p[1] >= 0 and p[1] != player) + \
                        sum(f[6] for f in fleets if f[1] >= 0 and f[1] != player)
    owned_fleet_ships = sum(f[6] for f in fleets if f[1] == player)
    fleet_commitment = owned_fleet_ships / max(total_owned_ships + owned_fleet_ships, 1)

    mode_2p = 1.0 if num_players == 2 else 0.0
    mode_4p = 1.0 if num_players == 4 else 0.0

    global_feats = np.array([
        player / max(num_players - 1, 1),
        step / 500.0,
        angular_velocity / 0.05,
        num_owned / 10.0,
        total_owned_ships / 500.0,
        total_owned_production / 20.0,
        total_enemy_ships / 2000.0,
        fleet_commitment,
        mode_2p,
        mode_4p,
    ], dtype=np.float32)

    return {
        "planet_features": torch.from_numpy(planet_feats),
        "fleet_features": torch.from_numpy(fleet_feats),
        "global_features": torch.from_numpy(global_feats),
        "planet_mask": torch.from_numpy(planet_mask),
        "fleet_mask": torch.from_numpy(fleet_mask_arr),
        "owned_indices": torch.from_numpy(owned_indices),
        "owned_count": owned_count,
    }


# --- Action masks (inlined from action_mask.py) ---












NUM_ANGLE_BINS = 72
ANGLE_BIN_WIDTH = 2 * math.pi / NUM_ANGLE_BINS
CENTER = 50.0
SUN_RADIUS = 10.0
BOARD_SIZE = 100.0
MAX_OWNED_PLANETS = 10

ANGLE_BIN_CENTERS = np.array([(i + 0.5) * ANGLE_BIN_WIDTH for i in range(NUM_ANGLE_BINS)])


def compute_action_masks(obs, player, max_owned=MAX_OWNED_PLANETS):
    """Compute action masks from observation dict.

    Returns dict with torch tensors (batch dim 0=1):
        - fire_mask: (1, max_owned) bool
        - angle_mask: (1, max_owned, 72) bool
        - max_ships: (1, max_owned) int
        - owned_indices: (max_owned,) int — indices into planet array
        - owned_count: int
        - slot_valid: (1, max_owned) bool
    """
    planets = obs["planets"]
    fleets = obs["fleets"]

    # Find owned planets
    my_planets = [(i, p) for i, p in enumerate(planets) if p[1] == player]
    n_owned = min(len(my_planets), max_owned)

    owned_indices = np.zeros(max_owned, dtype=np.int64)
    fire_mask = np.zeros(max_owned, dtype=np.bool_)
    angle_mask = np.zeros((max_owned, NUM_ANGLE_BINS), dtype=np.bool_)
    max_ships_arr = np.zeros(max_owned, dtype=np.int64)
    slot_valid = np.zeros(max_owned, dtype=np.bool_)

    # Compute incoming fleet pressure per planet (for future use)
    fleet_cos = np.array([math.cos(f[4]) for f in fleets]) if fleets else np.array([])
    fleet_sin = np.array([math.sin(f[4]) for f in fleets]) if fleets else np.array([])

    for slot, (idx, p) in enumerate(my_planets[:max_owned]):
        slot_valid[slot] = True
        owned_indices[slot] = idx
        px, py, pr, ps = p[2], p[3], p[4], p[5]

        fire_mask[slot] = ps > 1
        max_ships_arr[slot] = max(0, int(ps) - 1)

        # Compute legal angles: launch from just outside planet radius
        spawn_x = px + (pr + 0.1) * np.cos(ANGLE_BIN_CENTERS)
        spawn_y = py + (pr + 0.1) * np.sin(ANGLE_BIN_CENTERS)

        # Check 1) out of bounds
        in_bounds = (spawn_x >= 0) & (spawn_x <= BOARD_SIZE) & (spawn_y >= 0) & (spawn_y <= BOARD_SIZE)

        # Check 2) sun crossing — check line segment from spawn to spawn + direction * some distance
        # Use a segment length of ~20 (typical fleet travel) for sun crossing check
        check_dist = 20.0
        end_x = spawn_x + check_dist * np.cos(ANGLE_BIN_CENTERS)
        end_y = spawn_y + check_dist * np.sin(ANGLE_BIN_CENTERS)

        # Point-to-segment distance from sun center to spawn->end segment
        sun_dist = _point_segment_distance_array(CENTER, CENTER, spawn_x, spawn_y, end_x, end_y)
        not_cross_sun = sun_dist > SUN_RADIUS

        angle_mask[slot] = in_bounds & not_cross_sun

    # Convert to torch tensors with batch dim
    return {
        "fire_mask": torch.from_numpy(fire_mask).unsqueeze(0),
        "angle_mask": torch.from_numpy(angle_mask).unsqueeze(0),
        "max_ships": torch.from_numpy(max_ships_arr).unsqueeze(0),
        "owned_indices": torch.from_numpy(owned_indices),
        "owned_count": n_owned,
        "slot_valid": torch.from_numpy(slot_valid).unsqueeze(0),
    }


def _point_segment_distance_array(px, py, ax_arr, ay_arr, bx_arr, by_arr):
    """Vectorized point-segment distance from (px,py) to segments (ax,ay)->(bx,by)."""
    dx = bx_arr - ax_arr
    dy = by_arr - ay_arr
    l2 = dx * dx + dy * dy
    t = np.where(l2 < 1e-12, 0.0, np.clip(((px - ax_arr) * dx + (py - ay_arr) * dy) / np.maximum(l2, 1e-12), 0, 1))
    proj_x = ax_arr + t * dx
    proj_y = ay_arr + t * dy
    return np.sqrt((px - proj_x) ** 2 + (py - proj_y) ** 2)


def actions_from_policy(fire_probs, angle_logits, ship_logits, masks, obs, player, fire_threshold=0.5):
    """Convert policy outputs to environment action format.

    Returns: list of [from_planet_id, angle_radians, ship_count]
    """
    planets = obs["planets"]
    my_planets = [(i, p) for i, p in enumerate(planets) if p[1] == player]
    owned_indices = masks["owned_indices"].cpu().numpy()
    max_ships = masks["max_ships"].cpu().numpy().squeeze(0)

    fire_decisions = (torch.sigmoid(fire_probs) > fire_threshold).cpu().numpy().squeeze(0)
    angle_bins = torch.argmax(angle_logits, dim=-1).cpu().numpy().squeeze(0)
    ship_bins = torch.argmax(ship_logits, dim=-1).cpu().numpy().squeeze(0)

    moves = []
    max_moves = 8
    for slot in range(min(masks["owned_count"], fire_decisions.shape[0])):
        if len(moves) >= max_moves:
            break
        if not fire_decisions[slot]:
            continue

        pidx = int(owned_indices[slot])
        if pidx >= len(planets):
            continue
        from_id = int(planets[pidx][0])

        angle = float(angle_bins[slot] * ANGLE_BIN_WIDTH + ANGLE_BIN_WIDTH / 2)
        ships = _ship_bin_to_count(int(ship_bins[slot]), int(max_ships[slot]))
        if ships > 0 and planets[pidx][5] > ships:
            moves.append([from_id, angle, ships])

    return moves


def actions_from_sampled_policy(fire_action, angle_action, ship_action, masks, obs, player):
    """Convert sampled policy action tensors to environment action format."""
    planets = obs["planets"]
    owned_indices = masks["owned_indices"].cpu().numpy()
    max_ships = masks["max_ships"].cpu().numpy().squeeze(0)

    fire_decisions = fire_action.cpu().numpy().squeeze(0).astype(bool)
    angle_bins = angle_action.cpu().numpy().squeeze(0)
    ship_bins = ship_action.cpu().numpy().squeeze(0)

    moves = []
    max_moves = 8
    for slot in range(min(masks["owned_count"], fire_decisions.shape[0])):
        if len(moves) >= max_moves:
            break
        if not fire_decisions[slot]:
            continue

        pidx = int(owned_indices[slot])
        if pidx >= len(planets):
            continue
        from_id = int(planets[pidx][0])

        angle = float(int(angle_bins[slot]) * ANGLE_BIN_WIDTH + ANGLE_BIN_WIDTH / 2)
        ships = _ship_bin_to_count(int(ship_bins[slot]), int(max_ships[slot]))
        if ships > 0 and planets[pidx][5] > ships:
            moves.append([from_id, angle, ships])

    return moves


SHIP_COUNTS = [1, 2, 3, 5, 8, 13, 20, 30, 45, 65, 90, 120, 160, 200, 250, 300]


def _ship_bin_to_count(bin_idx, max_ships):
    return min(SHIP_COUNTS[bin_idx], max(1, max_ships))



# --- Kaggle agent entry point ---

def agent(obs):
    model = _get_model()

    if not isinstance(obs, dict):
        obs = {
            "step": int(getattr(obs, "step", 0)),
            "player": int(getattr(obs, "player", 0)),
            "planets": [[p.id, p.owner, p.x, p.y, p.radius, p.ships, p.production]
                        for p in obs.planets],
            "fleets": [[f.id, f.owner, f.x, f.y, f.angle, f.from_planet_id, f.ships]
                       for f in obs.fleets],
            "angular_velocity": float(getattr(obs, "angular_velocity", 0.0)),
            "initial_planets": [[p.id, p.owner, p.x, p.y, p.radius, p.ships, p.production]
                                 for p in getattr(obs, "initial_planets", obs.planets)],
            "comet_planet_ids": list(getattr(obs, "comet_planet_ids", [])),
        }

    player = obs["player"]
    features = extract_features(obs, player, num_players=2)
    masks = compute_action_masks(obs, player)

    with torch.no_grad():
        out = model(
            features["planet_features"].unsqueeze(0),
            features["fleet_features"].unsqueeze(0),
            features["global_features"].unsqueeze(0),
            features["planet_mask"].unsqueeze(0),
            features["fleet_mask"].unsqueeze(0),
            fire_mask=masks["fire_mask"],
            angle_mask=masks["angle_mask"],
            slot_valid=masks["slot_valid"],
            owned_indices=masks["owned_indices"].unsqueeze(0),
        )

    return actions_from_policy(
        out["fire_logits"],
        out["angle_logits"],
        out["ship_logits"],
        {k: v.cpu() if isinstance(v, torch.Tensor) else v for k, v in masks.items()},
        obs, player,
        fire_threshold=_FIRE_THRESHOLD,
    )
